import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"Permissions & Data Scope Engine","description":"","frontmatter":{},"headers":[],"relativePath":"permissions/README.md","filePath":"permissions/README.md"}'),d={name:"permissions/README.md"};function r(i,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="permissions-data-scope-engine" tabindex="-1">Permissions &amp; Data Scope Engine <a class="header-anchor" href="#permissions-data-scope-engine" aria-label="Permalink to &quot;Permissions &amp; Data Scope Engine&quot;">​</a></h1><p>A dual-engine access-control system: one engine decides which <strong>screens/actions</strong> a user can reach (functional permissions), a second, fully independent engine decides which <strong>data rows</strong> that user can see once inside a screen (data scope). Every feature documented here is implemented and covered by Pest tests unless explicitly marked 🔮 Planned or ❌ Unsupported — see <a href="./testing">testing.md</a> for what&#39;s verified.</p><h2 id="why-two-engines-not-one" tabindex="-1">Why two engines, not one <a class="header-anchor" href="#why-two-engines-not-one" aria-label="Permalink to &quot;Why two engines, not one&quot;">​</a></h2><p>A single permission check answering &quot;can this user see invoices?&quot; cannot also answer &quot;which company&#39;s invoices?&quot; — conflating the two into one mechanism is the most common way access control collapses in an ERP (a scope bug looks like a permission bug and vice versa, and fixing one silently breaks the other). This system keeps them structurally separate:</p><table tabindex="0"><thead><tr><th>Question</th><th>Mechanism</th><th>Core class</th></tr></thead><tbody><tr><td>&quot;Which screens/actions can this user open?&quot;</td><td>Spatie roles/permissions, auto-synced from the org structure</td><td><code>App\\Support\\Organization\\EmployeePermissionSynchronizer</code></td></tr><tr><td>&quot;Which data rows can this user see?&quot;</td><td>A resolved, cached set of entity/branch/department ids</td><td><code>App\\Support\\Organization\\OrganizationScopeResolver</code></td></tr></tbody></table><p>Both checks apply on every request, independently. A Sales Manager can have full data-scope visibility across the whole company and still get <code>can(&#39;fin-gl-jou.view&#39;) === false</code> — rank in the org tree has no bearing on functional access, and a wide functional grant has no bearing on which rows come back from a query.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><ul><li><strong>Org structure</strong> (<code>Modules/HR/Models/OrganizationStructure/</code>) — <code>Entity</code>, <code>Branch</code>, <code>Department</code> (a group-wide catalog, not one row per company — see <a href="./data-scope#departments-are-a-shared-catalog">data-scope.md</a>), <code>JobTitle</code>, <code>JobGrade</code>. <code>Entity</code>/<code>Department</code> use a materialized <code>path</code> column for descendant queries.</li><li><strong>The pivotal record</strong> — <code>Modules\\HR\\Models\\EmployeeManagement\\Employee</code> is the only bridge between a logged-in <code>User</code> and the org structure. See <a href="./data-scope">data-scope.md</a>.</li><li><strong>Data scope engine</strong> (<code>app/Support/Organization/</code>) — <code>OrganizationScopeResolver</code>, <code>OrganizationScope</code> (the resolved value object), <code>OrganizationVersion</code> (cache invalidation), <code>OrganizationScopeConstraint</code> (the Eloquent global scope), and the <code>App\\Models\\Concerns\\ScopedToOrganization</code> trait any model opts into.</li><li><strong>Functional permissions engine</strong> — <code>php artisan permissions:sync</code> generates every Spatie permission from the existing <code>modules</code>/<code>sub_modules</code>/<code>applications</code> code hierarchy; <code>department_permissions</code> / <code>job_title_permissions</code> / <code>job_title_grade_permissions</code> / <code>job_title_grade_roles</code> are the grant tables; <code>EmployeePermissionSynchronizer</code> is the only writer to <code>model_has_permissions</code>/<code>model_has_roles</code>; <code>php artisan hr:permissions:reconcile</code> is the drift backstop.</li></ul><h2 id="feature-matrix" tabindex="-1">Feature matrix <a class="header-anchor" href="#feature-matrix" aria-label="Permalink to &quot;Feature matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th></tr></thead><tbody><tr><td>Entity/Branch/Department/JobTitle/JobGrade org structure, with materialized-path trees</td><td>✅ Implemented</td></tr><tr><td>Departments as a group-wide catalog shared across entities (<code>department_entity</code> pivot)</td><td>✅ Implemented</td></tr><tr><td><code>Employee</code> as the single User↔org-structure bridge</td><td>✅ Implemented</td></tr><tr><td>Two-dimensional data scope (<code>entity_scope</code> × <code>department_scope</code>, resolved as an intersection)</td><td>✅ Implemented</td></tr><tr><td>Cached scope resolution with single-counter invalidation (<code>OrganizationVersion</code>)</td><td>✅ Implemented</td></tr><tr><td><code>ScopedToOrganization</code> trait — opt-in global scope for any model, any module</td><td>✅ Implemented</td></tr><tr><td>Fail-closed on no authenticated user / no active <code>Employee</code> row</td><td>✅ Implemented</td></tr><tr><td>Fail-closed (not a crash) on a soft-deleted entity/department mid-tree</td><td>✅ Implemented</td></tr><tr><td><code>super_admin</code> bypass for both engines independently</td><td>✅ Implemented</td></tr><tr><td>Permission auto-generation from the module/sub_module/application code hierarchy</td><td>✅ Implemented — <code>permissions:sync</code></td></tr><tr><td>Grant tables: department / job title / job-title-and-grade-and-above / named roles</td><td>✅ Implemented</td></tr><tr><td>Automatic Spatie sync on employee hire/reassignment/promotion/termination</td><td>✅ Implemented</td></tr><tr><td>Drift detection &amp; correction (<code>hr:permissions:reconcile</code>, with <code>--dry-run</code>)</td><td>✅ Implemented</td></tr><tr><td>Navigation tree (sidebar) filtered by functional permission at all 3 levels (module/sub_module/application)</td><td>✅ Implemented</td></tr><tr><td>Field-level permissions (e.g. hide a cost column from some job titles)</td><td>✅ Implemented — via <code>Column::visible()</code> / <code>ViewField</code> visibility callbacks; no new mechanism needed</td></tr><tr><td>Employee self-service (<code>own</code> scope) as a distinct data-scope value</td><td>✅ Implemented (scope value only — the ESS submodule&#39;s screens are not yet built)</td></tr><tr><td>Department-level manager auto-inheriting scope over sub-departments</td><td>✅ Implemented — <code>department_scope = department_tree</code></td></tr><tr><td>Regional/multi-branch manager scope grants beyond one branch</td><td>🔮 Planned — <code>hr_employee_scope_grants</code> (additive grant table, additive to <code>entity_scope</code>)</td></tr><tr><td>Employee assignment history (salary/job-title changes over time)</td><td>🔮 Planned — <code>employee_assignment_history</code></td></tr><tr><td>Approval workflows (multi-step document sign-off, exceptions)</td><td>🔮 Planned — separate engine, deliberately deferred</td></tr><tr><td>Edit/update forms for org-structure records</td><td>❌ Not implemented — <code>DynamicForm</code> is create-only in this pass; corrections go through direct DB access or a future update-form pass</td></tr><tr><td>UI to manage <code>department_entity</code> / <code>job_title_grade</code> attachments</td><td>❌ Not implemented — attach via <code>Department::attachToEntity()</code> / <code>JobTitle::jobGrades()-&gt;attach()</code> directly; the record-view &quot;Companies&quot;/&quot;Grades&quot; tabs are read-only</td></tr></tbody></table><p>This matrix is maintained honestly — update it when a row&#39;s status changes, not just when a feature ships.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Nothing to install. Built entirely on packages already present: Laravel 13, <code>spatie/laravel-permission</code> 8.3 (previously installed, unused before this engine), Livewire 4, Pest 5. No new Composer package was added.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./data-scope">data-scope.md</a> — the org tree, the <code>Employee</code> record, <code>entity_scope</code> / <code>department_scope</code>, caching and invalidation, the <code>ScopedToOrganization</code> trait.</li><li><a href="./functional-permissions">functional-permissions.md</a> — permission generation, the grant tables, the synchronizer, drift reconciliation.</li><li><a href="./testing">testing.md</a> — the full scenario matrix and where each is proven.</li><li>End users: <a href="./../user-guide/permissions">../user-guide/permissions.md</a> — granting/revoking a person&#39;s access, in plain terms, no code.</li></ul>',15)])])}const u=t(d,[["render",r]]);export{h as __pageData,u as default};
